//
//Calculate equation of circle given 3 points
//Description of variables
//  (x1, y1), (x2, y2), and (x3, y3): the given 3 points
//  (x0, y0): calculated center point
//  r: calculated radius
//
int calculateCircle3Points_tri2d(const double x1, const double y1, const double x2, const double y2,
		const double x3, const double y3, double &x0, double &y0, double &r){
	double zero = 0.0;
	double x1y1 = x1*x1+y1*y1;
	double x2y2 = x2*x2+y2*y2;
	double x3y3 = x3*x3+y3*y3;
	double x0det = x1*(y3-y2)+x2*(y1-y3)+x3*(y2-y1);
	double y0det = y1*(x3-x2)+y2*(x1-x3)+y3*(x2-x1);

	if (x0det == zero || y0det == zero) return 0;

	x0 = 0.5*(x1y1*(y3-y2) + x2y2*(y1-y3) + x3y3*(y2-y1))/x0det;
	y0 = 0.5*(x1y1*(x3-x2) + x2y2*(x1-x3) + x3y3*(x2-x1))/y0det;
	r = sqrt((x1-x0)*(x1-x0) + (y1-y0)*(y1-y0));

	return 1;
}

//
//Calculate the angle in Cartesian coordinates based on the cosine and sine value
//Description of variables
//  cosangle: input cosine value of the angle
//  sinangle: input sine value of the given angle
//  calculateAngle: return the angle in Cartesian coordinates [0-2Pi)
//
double calculateAngle_tri2d(const double cosangle, const double sinangle){
	double angle = 0.0;
	double pi = 3.141592653589793;
	if(cosangle >= 0 && sinangle >= 0)     //quadrant 1
		angle = asin(sinangle);
	else if(cosangle < 0 && sinangle >= 0) //quadrant 2
		angle = pi - asin(sinangle);
	else if(cosangle < 0 && sinangle < 0)  //quadrant 3
		angle = pi - asin(sinangle);
	else if(cosangle >= 0 && sinangle < 0)  //quadrant 4
		angle = 2.0*pi + asin(sinangle);
	return angle;
}

//
//Check the direction of the given 3 points, return true if it is counter-clockwise,
//  return false if it is clockwise
//Description of variables
//  (x1, y1), (x2, y2), and (x3, y3): the given 3 points
//  isCounterClockwise: true if the given 3 points are counter-clockwise, otherwise, false
//
bool isCounterClockwise_tri2d(const double x1, const double y1, const double x2, const double y2,
		const double x3, const double y3){
	double area = ((x2-x1)*(y3-y1)-(x3-x1)*(y2-y1))*0.5;
	if (area > 0.0)
		return true;
	else
		return false;
}

//
//Partition Arc to small ones based on the given interval
//Description of variables
//  (x1, y1) and (x2, y2): the beginning and end point of the arc
//  (x0, y0): the center point of the arc (circle)
//  r: radius of the arc (circle)
//  isCounter: direction of the arc, if true, it is couter-clockwise, otherwise, clockwise
//  delt_arc: the given interval (arc length)
//  vp: returned internal vertices, without the beginning and end point
//
void partitionArcPoints_tri2d(const double x1, const double y1, const double x2, const double y2,
		const double x0, const double y0, const double r, const bool isCounter,
		const double delt_arc, Vector_Point &vp){
	//convert Cartesian coordinates to Polar coordinates
	double pi = 3.141592653589793;
	double xx1 = x1 - x0;
	double yy1 = y1 - y0;
    double xx2 = x2 - x0;
    double yy2 = y2 - y0;
    double cos1 = xx1/r;
    double sin1 = yy1/r;
    double cos2 = xx2/r;
    double sin2 = yy2/r;
    double angle1 = calculateAngle_tri2d(cos1, sin1);
    double angle2 = calculateAngle_tri2d(cos2, sin2);

    if (isCounter){
    	if (angle2 < angle1){
    		angle2 = 2.0*pi + angle2;
    	}
    }
    else{
    	if (angle2 > angle1){
    		angle2 = -2.0*pi + angle2;
    	}
    }

    double angle = angle2 - angle1;
    double arclen = fabs(angle*r);
    int n = ceil(arclen/delt_arc);
    double delt_angle = angle/n;

    double x, y;
    for (int i = 1; i < n; i++){
    	x = r*cos(angle1+delt_angle*i)+x0;
    	y = r*sin(angle1+delt_angle*i)+y0;
    	vp.push_back(Point(x,y));
    }

}

//
//Insert a polyline into the CDT object, the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	mesh_cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	isclosed: if true, it is closed, if false, it is open.
//
void insertConstraintPolyline_tri2d(const Vector_Point vp, const bool isclosed){
	Vertex_handle vt1;
	Vertex_handle vt2;
	int n =  vp.size();
	for (int i = 0; i < n-1; i++){
		vt1 = mesh_cdt.insert(vp[i]);
		vt2 = mesh_cdt.insert(vp[i+1]);
		mesh_cdt.insert_constraint(vt1, vt2);
	}
	if (n > 2 && isclosed){
		vt1 = mesh_cdt.insert(vp[n-1]);
		vt2 = mesh_cdt.insert(vp[0]);
		mesh_cdt.insert_constraint(vt1, vt2);
	}
	is_constrained = true;
}

//
//Insert a polyline with distance input for every segment into the CDT object,
//the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	vd: double vector to define the point distribution interval in every segment
//	isclosed: if true, it is closed, if false, it is open.
//
void insertConstraintPolyline_tri2d(const Vector_Point vp, const Vector_double vd, const bool isclosed){
	int seg_n;
	double seg_l, seg_d, delt_x, delt_y;
	int n =  vp.size();
	for (int i = 0; i < n-1; i++){
		seg_l = sqrt(pow(vp[i+1].x()-vp[i].x(),2)+pow(vp[i+1].y()-vp[i].y(),2));
		seg_d = vd[i];
		seg_n = ceil(seg_l/seg_d);
		delt_x = (vp[i+1].x()-vp[i].x())/seg_n;
		delt_y = (vp[i+1].y()-vp[i].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[i].x(),vp[i].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[i].x()+delt_x*j,vp[i].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[i+1].x(),vp[i+1].y()));
		insertConstraintPolyline_tri2d(seg_pts, false);
	}
	if (n > 2 && isclosed){
		seg_l = sqrt(pow(vp[0].x()-vp[n-1].x(),2)+pow(vp[0].y()-vp[n-1].y(),2));
		seg_d = vd[n-1];
		seg_n = ceil(seg_l/seg_d);
		delt_x = (vp[0].x()-vp[n-1].x())/seg_n;
		delt_y = (vp[0].y()-vp[n-1].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[n-1].x(),vp[n-1].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[n-1].x()+delt_x*j,vp[n-1].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[0].x(),vp[0].y()));
		insertConstraintPolyline_tri2d(seg_pts, false);
	}
}

//
//Insert a polyline with distance input for every segment into the CDT object,
//the polyline can be open or closed (connect the fist and last point)
//Description of variables
//	cdt: Constrained_Delaunay_triangulation_2 object.
//	vp: Point vector to construct the polyline or polygon.
//	vi: integer vector to define the number of interval in every segment
//	isclosed: if true, it is closed, if false, it is open.
//
void insertConstraintPolyline_tri2d(const Vector_Point vp, const Vector_int vi, const bool isclosed){
	int seg_n;
	double seg_l, delt_x, delt_y;
	int n =  vp.size();
	for (int i = 0; i < n-1; i++){
		seg_l = sqrt(pow(vp[i+1].x()-vp[i].x(),2)+pow(vp[i+1].y()-vp[i].y(),2));
		seg_n = vi[i];
		delt_x = (vp[i+1].x()-vp[i].x())/seg_n;
		delt_y = (vp[i+1].y()-vp[i].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[i].x(),vp[i].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[i].x()+delt_x*j,vp[i].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[i+1].x(),vp[i+1].y()));
		insertConstraintPolyline_tri2d(seg_pts, false);
	}
	if (n > 2 && isclosed){
		seg_l = sqrt(pow(vp[0].x()-vp[n-1].x(),2)+pow(vp[0].y()-vp[n-1].y(),2));
		seg_n = vi[n-1];
		delt_x = (vp[0].x()-vp[n-1].x())/seg_n;
		delt_y = (vp[0].y()-vp[n-1].y())/seg_n;
		Vector_Point seg_pts;
		seg_pts.push_back(Point(vp[n-1].x(),vp[n-1].y()));
		for (int j = 1;j < seg_n; j++){
			seg_pts.push_back(Point(vp[n-1].x()+delt_x*j,vp[n-1].y()+delt_y*j));
		}
		seg_pts.push_back(Point(vp[0].x(),vp[0].y()));
		insertConstraintPolyline_tri2d(seg_pts, false);
	}
}

void insertConstraintPolygon_tri2d(const Polygon_2 polygon, const bool isclosed){
	mesh_cdt.insert_constraint(polygon.vertices_begin(), polygon.vertices_end(), isclosed);
	is_constrained = true;
}

//
//Insert circle or arc into CDT object
//Description of variables
//  pt1, pt2 and pt3 are the given 3 points
//  delt_arc: the given interval (arc length)
//  isClosed: if true, this is a circle, otherwise, it's an arc in the direction pt1->pt2->pt3
//
void insertConstraintCircle_tri2d(const Point pt1, const Point pt2, const Point pt3,
		const double delt_arc, const bool isClosed){

	double x0, y0, r;
	Vector_Point vp;

	bool isCounter = isCounterClockwise_tri2d(pt1.x(), pt1.y(), pt2.x(), pt2.y(), pt3.x(), pt3.y());

	int iflag = calculateCircle3Points_tri2d(pt1.x(), pt1.y(), pt2.x(), pt2.y(),
			pt3.x(), pt3.y(), x0, y0, r);

	if (iflag > 0){
		vp.push_back(pt1);
		partitionArcPoints_tri2d(pt1.x(), pt1.y(), pt2.x(), pt2.y(),
				x0, y0, r, isCounter, delt_arc, vp);
		vp.push_back(pt2);
		partitionArcPoints_tri2d(pt2.x(), pt2.y(), pt3.x(), pt3.y(),
				x0, y0, r, isCounter, delt_arc, vp);
		vp.push_back(pt3);
		if (isClosed)
			partitionArcPoints_tri2d(pt3.x(), pt3.y(), pt1.x(), pt1.y(),
					x0, y0, r, isCounter, delt_arc, vp);

		insertConstraintPolyline_tri2d(vp, isClosed);
	}
}


//
// 2d triangulation coordinate type
//
void setCoordinateType_tri2d(const int itype){
	itypeCoordinate_tri2d = itype;
}


// triangulation
void triangulation2d(){
	mesh_cdt.insert(mesh_points_tri2d.begin(),mesh_points_tri2d.end());

	mesh_vertices_counter_tri2d = 0;
	mesh_edges_counter_tri2d = 0;
	mesh_faces_counter_tri2d = 0;

	if (is_constrained){
		//Mark facets that are inside the domain bounded by the polygon
		mark_domains(mesh_cdt);

		// calculate the number of vertices
		for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
				vit != mesh_cdt.finite_vertices_end(); ++vit){
			mesh_vertices_counter_tri2d = mesh_vertices_counter_tri2d + 1;
		}

		// calculate the number of edges
		for (CDT::Finite_edges_iterator eit = mesh_cdt.finite_edges_begin();
			  eit != mesh_cdt.finite_edges_end();++eit){
		   if (mesh_cdt.is_constrained(*eit)) ++mesh_edges_counter_tri2d;
		}

		// calculate the nubmer of faces
		for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
				fit != mesh_cdt.finite_faces_end(); ++fit){
		  if(fit->info().in_domain()){
			  mesh_faces_counter_tri2d = mesh_faces_counter_tri2d + 1;
		  }
		}
	}
	else{
		// calculate the number of vertices
		for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
				vit != mesh_cdt.finite_vertices_end(); ++vit){
			mesh_vertices_counter_tri2d = mesh_vertices_counter_tri2d + 1;
		}

		// calculate the number of edges
		for (CDT::Finite_edges_iterator eit = mesh_cdt.finite_edges_begin();
			  eit != mesh_cdt.finite_edges_end();++eit){
			if (mesh_cdt.is_constrained(*eit)) ++mesh_edges_counter_tri2d;
		}

		// calculate the nubmer of faces
		for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
				fit != mesh_cdt.finite_faces_end(); ++fit){
			mesh_faces_counter_tri2d = mesh_faces_counter_tri2d + 1;
		}
	}

	cout << "number of vertices: " << mesh_vertices_counter_tri2d << endl;
	cout << "number of edges: " << mesh_edges_counter_tri2d << endl;
	cout << "number of faces: " << mesh_faces_counter_tri2d << endl;
}

// write mesh to file
void outputTriangulation2d(const int nfile,const char* sfile,const int nformat, const char* sformat){

	  std::string strfile(sfile,0,nfile);
	  std::string strformat(sformat,0,nformat);

	  // Output mesh 2D
	  std::ofstream out;

	  // Output the mesh to OFF (Object File Format)
	  out.open(strfile);

	  // Vertices list with index
	  std::map<Point, int> map_vts;

	  //Note: index in off file is 0-based and msh file format is 1-based
	  int icell = 0;
	  int ivertex = 0;

	  if (strformat == "off"){
		  //Note: index in off file format is 0-based
	      // Write header
	      out << "OFF" << endl;

	      //Off file head information
	      out << mesh_vertices_counter_tri2d << " "
        		  << mesh_faces_counter_tri2d << " "
				  << mesh_edges_counter_tri2d << endl;

          //Write vertex
		  for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
		  	  vit != mesh_cdt.finite_vertices_end(); ++vit){
			Point pt = vit->point();
			map_vts[pt] = ivertex;
			ivertex = ivertex + 1;
			if(itypeCoordinate_tri2d == 0){
				out << pt.x() << " " << pt.y() << " " << " 0" << endl;
			}
			else if(itypeCoordinate_tri2d == 1){
				out << " 0 " << pt.x() << " " << pt.y() << endl;
			}
			else if(itypeCoordinate_tri2d == 0){
				out << pt.x() << " 0 " << pt.y() << endl;
			}
		  }

		  //Write faces
		  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
		          fit != mesh_cdt.finite_faces_end(); ++fit){
			if (is_constrained){
			  if(fit->info().in_domain()){
				//Write 3-node triangles
				Point pt0 = fit->vertex(0)->point();
				Point pt1 = fit->vertex(1)->point();
				Point pt2 = fit->vertex(2)->point();
				out << "3 " << map_vts[pt0] << " "
			        << map_vts[pt1] << " " << map_vts[pt2] << endl;
			  }
			}
		    else{
			  //Write 3-node triangles
			  Point pt0 = fit->vertex(0)->point();
			  Point pt1 = fit->vertex(1)->point();
			  Point pt2 = fit->vertex(2)->point();
			  out << "3 " << map_vts[pt0] << " "
		          << map_vts[pt1] << " " << map_vts[pt2] << endl;
		    }
		  }
	  }
	  else if (strformat == "msh"){
		  //Note: index in msh file format is 1-based
		  // Output the mesh to file

		  // Write header
		  out << "$MeshFormat" << endl;
		  out << "2.2 0 8" << endl;
		  out << "$EndMeshFormat" << endl;
		  //Write nodes/vertices
		  out << "$Nodes" << endl;
		  out << mesh_vertices_counter_tri2d << endl;
		  for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
		  	  vit != mesh_cdt.finite_vertices_end(); ++vit){
			Point pt = vit->point();
			ivertex = ivertex + 1;
			map_vts[pt] = ivertex;
			if(itypeCoordinate_tri2d == 0){
				out << map_vts[pt] << " " << pt.x() << " " << pt.y() << " " << " 0" << endl;
			}
			else if(itypeCoordinate_tri2d == 1){
				out << map_vts[pt] << " 0 " << pt.x() << " " << pt.y() << endl;
			}
			else if(itypeCoordinate_tri2d == 2){
				out << map_vts[pt] << " " << pt.x() << " 0 " << pt.y() << endl;
			}
		  }
		  out << "$EndNodes" << endl;

		  // Write elements/cells
		  out << "$Elements" << endl;
		  out << mesh_faces_counter_tri2d << endl;
		  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
		          fit != mesh_cdt.finite_faces_end(); ++fit){
			if (is_constrained){
		      if(fit->info().in_domain()){
		    	icell = icell + 1;
		        //Write 3-node triangles, tags are set to 2 with tag value 0, hardwired
		        Point pt0 = fit->vertex(0)->point();
		        Point pt1 = fit->vertex(1)->point();
		        Point pt2 = fit->vertex(2)->point();
		    	out << icell << " 2 2 0 0 " << map_vts[pt0] << " "
		            << map_vts[pt1] << " " << map_vts[pt2] << endl;
		      }
			}
			else{
		      icell = icell + 1;
		      //Write 3-node triangles, tags are set to 2 with tag value 0, hardwired
		      Point pt0 = fit->vertex(0)->point();
		      Point pt1 = fit->vertex(1)->point();
		      Point pt2 = fit->vertex(2)->point();
		      out << icell << " 2 2 0 0 " << map_vts[pt0] << " "
		          << map_vts[pt1] << " " << map_vts[pt2] << endl;
			}
		  }
		  out << "$EndElements" << endl;
	  }
	  else if (strformat == "vtk"){
		  //Note: index in vtk file format is 0-based
		  // Output the mesh to file

		  // Write header
		  out << "# vtk DataFile Version 2.0" << endl;
		  out << "Unstructured grid based on CGAL triangulated 2d mesh" << endl;
		  out << "ASCII" << endl;
		  out << "DATASET UNSTRUCTURED_GRID" << endl;


		  //Write nodes/vertices
		  out << "POINTS " << mesh_vertices_counter_tri2d << " double" << endl;

		  for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
		  	  vit != mesh_cdt.finite_vertices_end(); ++vit){
			Point pt = vit->point();
			map_vts[pt] = ivertex;
			ivertex = ivertex + 1;

			if(itypeCoordinate_tri2d == 0){
				out << pt.x() << " " << pt.y() << " " << " 0" << endl;
			}
			else if(itypeCoordinate_tri2d == 1){
				out << "0 " << pt.x() << " " << pt.y() << endl;
			}
			else if(itypeCoordinate_tri2d == 2){
				out << pt.x() << " 0 " << pt.y() << endl;
			}
		  }
		  out << endl;

		  // Write elements/cells
		  out << "CELLS " << mesh_faces_counter_tri2d << " " << mesh_faces_counter_tri2d*4 << endl;

		  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
		          fit != mesh_cdt.finite_faces_end(); ++fit){
			if (is_constrained){
		      if(fit->info().in_domain()){
		        //Write 3-node triangles, tags are set to 2 with tag value 0, hardwired
		        Point pt0 = fit->vertex(0)->point();
		        Point pt1 = fit->vertex(1)->point();
		        Point pt2 = fit->vertex(2)->point();
		    	out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " " << map_vts[pt2] << endl;
		      }
			}
			else{
		      //Write 3-node triangles, tags are set to 2 with tag value 0, hardwired
		      Point pt0 = fit->vertex(0)->point();
		      Point pt1 = fit->vertex(1)->point();
		      Point pt2 = fit->vertex(2)->point();
		      out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " " << map_vts[pt2] << endl;
			}
		  }
		  out << endl;

		  // Write cell type
		  out << "CELL_TYPES " << mesh_faces_counter_tri2d << endl;

	      for (int icell = 0; icell < mesh_faces_counter_tri2d; icell++){
	    	  out << "5" << endl;
	      }
	  }
	  else{
		  out << "Error: output mesh format is unknown" << endl;
	  }
	  // Close file
	  out.close();
}

// write mesh to file
void outputTriangulationPrism(const int nfile,const char* sfile,const int nformat, const char* sformat){

	  std::string strfile(sfile,0,nfile);
	  std::string strformat(sformat,0,nformat);

	  // Output mesh 2D
	  std::ofstream out;

	  // Output the mesh to OFF (Object File Format)
	  out.open(strfile);

	  // Vertices list with index
	  std::map<Point, int> map_vts;

	  //Note: index in off file is 0-based and msh file format is 1-based
	  int icell = 0;
	  int ivertex = 0;

	  if (strformat == "off"){
		  //Note: index in off file format is 0-based
	      // Write header
	      out << "OFF" << endl;

	      //Off file head information
	      out << mesh_vertices_counter_tri2d*terrain_layers_n << " "
        		  << mesh_faces_counter_tri2d*terrain_layers_n+mesh_faces_counter_tri2d*3*(terrain_layers_n-1)<< " "
				  << mesh_edges_counter_tri2d*terrain_layers_n+ mesh_vertices_counter_tri2d*(terrain_layers_n-1)<< endl;

          //Write vertex
	      for (int ilayer = 0; ilayer < terrain_layers_n; ilayer++){
	    	  int idelt = ilayer*mesh_vertices_counter_tri2d;
			  for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
				  vit != mesh_cdt.finite_vertices_end(); ++vit){
				Point pt = vit->point();
				if(ilayer == 0){
					map_vts[pt] = ivertex;
				}
				out << pt.x() << " " << pt.y() << " " << terrain_layers_z[mesh_points_map[pt]+idelt] << endl;
				ivertex = ivertex + 1;
			  }
	      }

		  //Write faces
	      if(terrain_layers_n == 1){
			  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
					  fit != mesh_cdt.finite_faces_end(); ++fit){
				if (is_constrained){
				  if(fit->info().in_domain()){
					//Write 3-node triangles
					Point pt0 = fit->vertex(0)->point();
					Point pt1 = fit->vertex(1)->point();
					Point pt2 = fit->vertex(2)->point();
					//face, suppose node is counter-clockwise
					out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " " << map_vts[pt2] << endl;
				  }
				}
				else{
					//Write 3-node triangles
					Point pt0 = fit->vertex(0)->point();
					Point pt1 = fit->vertex(1)->point();
					Point pt2 = fit->vertex(2)->point();
					//face, suppose node is counter-clockwise
					out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " " << map_vts[pt2] << endl;
				}
			  }
	      }
	      else if (terrain_layers_n > 1){
			  for (int ilayer = 0; ilayer < terrain_layers_n-1; ilayer++){
				  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
						  fit != mesh_cdt.finite_faces_end(); ++fit){
					int idelt = ilayer*mesh_vertices_counter_tri2d;
					int idelt2 = (ilayer+1)*mesh_vertices_counter_tri2d;
					if (is_constrained){
					  if(fit->info().in_domain()){
						//Write 3-node triangles
						Point pt0 = fit->vertex(0)->point();
						Point pt1 = fit->vertex(1)->point();
						Point pt2 = fit->vertex(2)->point();
						//Bottom face, suppose node is counter-clockwise
						out << "3 " << map_vts[pt2]+idelt << " "
							<< map_vts[pt1]+idelt << " " << map_vts[pt0]+idelt << endl;
						//Side face
						out << "4 " << map_vts[pt0]+idelt << " " << map_vts[pt1]+idelt << " "
							<< map_vts[pt1]+idelt2 << " " << map_vts[pt0]+idelt2 << endl;
						out << "4 " << map_vts[pt1]+idelt << " " << map_vts[pt2]+idelt << " "
							<< map_vts[pt2]+idelt2 << " " << map_vts[pt1]+idelt2 << endl;
						out << "4 " << map_vts[pt2]+idelt << " " << map_vts[pt0]+idelt << " "
							<< map_vts[pt0]+idelt2 << " " << map_vts[pt2]+idelt2 << endl;
						//Top face
						out << "3 " << map_vts[pt0]+idelt2 << " "
							<< map_vts[pt1]+idelt2 << " " << map_vts[pt2]+idelt2 << endl;
					  }
					}
					else{
						//Write 3-node triangles
						Point pt0 = fit->vertex(0)->point();
						Point pt1 = fit->vertex(1)->point();
						Point pt2 = fit->vertex(2)->point();
						//Bottom face, suppose node is counter-clockwise
						out << "3 " << map_vts[pt2]+idelt << " "
							<< map_vts[pt1]+idelt << " " << map_vts[pt0]+idelt << endl;
						//Side face
						out << "4 " << map_vts[pt0]+idelt << " " << map_vts[pt1]+idelt << " "
							<< map_vts[pt1]+idelt2 << " " << map_vts[pt0]+idelt2 << endl;
						out << "4 " << map_vts[pt1]+idelt << " " << map_vts[pt2]+idelt << " "
							<< map_vts[pt2]+idelt2 << " " << map_vts[pt1]+idelt2 << endl;
						out << "4 " << map_vts[pt2]+idelt << " " << map_vts[pt0]+idelt << " "
							<< map_vts[pt0]+idelt2 << " " << map_vts[pt2]+idelt2 << endl;
						//Top face
						out << "3 " << map_vts[pt0]+idelt2 << " "
							<< map_vts[pt1]+idelt2 << " " << map_vts[pt2]+idelt2 << endl;
					}
				  }
			  }
	      }

	  }
	  else if (strformat == "msh"){
		  //Note: index in msh file format is 1-based
		  // Output the mesh to file

		  // Write header
		  out << "$MeshFormat" << endl;
		  out << "2.2 0 8" << endl;
		  out << "$EndMeshFormat" << endl;
		  //Write nodes/vertices
		  out << "$Nodes" << endl;
		  out << mesh_vertices_counter_tri2d*terrain_layers_n << endl;

	      for (int ilayer = 0; ilayer < terrain_layers_n; ilayer++){
	    	  int idelt = ilayer*mesh_vertices_counter_tri2d;
			  for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
				  vit != mesh_cdt.finite_vertices_end(); ++vit){
				Point pt = vit->point();
				if(ilayer == 0){
					map_vts[pt] = ivertex+1;
				}
				out << map_vts[pt]+idelt<< " " << pt.x() << " " << pt.y() << " " << terrain_layers_z[mesh_points_map[pt]+idelt] << endl;
				ivertex = ivertex + 1;
			  }
	      }
		  out << "$EndNodes" << endl;

		  // Write elements/cells
		  out << "$Elements" << endl;
		  if(terrain_layers_n == 1){
			  out << mesh_faces_counter_tri2d << endl;

			  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
					  fit != mesh_cdt.finite_faces_end(); ++fit){
				if (is_constrained){
				  if(fit->info().in_domain()){
					icell = icell + 1;
					//Write 6-node prism
					Point pt0 = fit->vertex(0)->point();
					Point pt1 = fit->vertex(1)->point();
					Point pt2 = fit->vertex(2)->point();
					out << icell << " 2 2 0 0 " << map_vts[pt0] << " "
						<< map_vts[pt1] << " " << map_vts[pt2] << endl;
				  }
				}
				else{
				  icell = icell + 1;
				  //Write 6-node prism
				  Point pt0 = fit->vertex(0)->point();
				  Point pt1 = fit->vertex(1)->point();
				  Point pt2 = fit->vertex(2)->point();
					out << icell << " 2 2 0 0 " << map_vts[pt0] << " "
						<< map_vts[pt1] << " " << map_vts[pt2] << endl;
				}
			  }
		  }
		  else if(terrain_layers_n > 1){
			  out << mesh_faces_counter_tri2d*(terrain_layers_n-1) << endl;
			  for (int ilayer = 0; ilayer < terrain_layers_n-1; ilayer++){
				  int idelt = ilayer*mesh_vertices_counter_tri2d;
				  int idelt2 = (ilayer+1)*mesh_vertices_counter_tri2d;
				  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
						  fit != mesh_cdt.finite_faces_end(); ++fit){
					if (is_constrained){
					  if(fit->info().in_domain()){
						icell = icell + 1;
						//Write 6-node prism
						Point pt0 = fit->vertex(0)->point();
						Point pt1 = fit->vertex(1)->point();
						Point pt2 = fit->vertex(2)->point();
						out << icell << " 6 2 0 0 " << map_vts[pt0]+idelt << " "
							<< map_vts[pt1]+idelt << " " << map_vts[pt2]+idelt << " "
							<< map_vts[pt0]+idelt2 << " " << map_vts[pt1]+idelt2 << " "
							<< map_vts[pt2]+idelt2 << endl;
					  }
					}
					else{
					  icell = icell + 1;
					  //Write 6-node prism
					  Point pt0 = fit->vertex(0)->point();
					  Point pt1 = fit->vertex(1)->point();
					  Point pt2 = fit->vertex(2)->point();
						out << icell << " 6 2 0 0 " << map_vts[pt0]+idelt << " "
							<< map_vts[pt1]+idelt << " " << map_vts[pt2]+idelt << " "
							<< map_vts[pt0]+idelt2 << " " << map_vts[pt1]+idelt2 << " "
							<< map_vts[pt2]+idelt2 << endl;
					}
				  }
			  }
		  }

		  out << "$EndElements" << endl;
	  }
	  else if (strformat == "vtk"){
		  //Note: index in vtk file format is 0-based
		  // Output the mesh to file

		  // Write header
		  out << "# vtk DataFile Version 2.0" << endl;
		  out << "Prism unstructured grid based on CGAL triangulated 2d mesh" << endl;
		  out << "ASCII" << endl;
		  out << "DATASET UNSTRUCTURED_GRID" << endl;

		  //Write nodes/vertices
		  int nvtx = mesh_vertices_counter_tri2d*terrain_layers_n;
		  out << "POINTS " << nvtx << " double" << endl;

	      for (int ilayer = 0; ilayer < terrain_layers_n; ilayer++){
	    	  int idelt = ilayer*mesh_vertices_counter_tri2d;
			  for(CDT::Finite_vertices_iterator vit = mesh_cdt.finite_vertices_begin();
				  vit != mesh_cdt.finite_vertices_end(); ++vit){
				Point pt = vit->point();
				if(ilayer == 0){
					map_vts[pt] = ivertex;
				}
				out << pt.x() << " " << pt.y() << " " << terrain_layers_z[mesh_points_map[pt]+idelt] << endl;
				ivertex = ivertex + 1;
			  }
	      }
		  out << endl;

		  // Write elements/cells
		  if(terrain_layers_n == 1){
			  int ncells = mesh_faces_counter_tri2d;
			  out << "CELLS " << ncells << " " << ncells*4 << endl;

			  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
					  fit != mesh_cdt.finite_faces_end(); ++fit){
				if (is_constrained){
					if(fit->info().in_domain()){
						//Write 3-node triangle
						Point pt0 = fit->vertex(0)->point();
						Point pt1 = fit->vertex(1)->point();
						Point pt2 = fit->vertex(2)->point();
						out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " " << map_vts[pt2] << endl;
					}
				}
				else{
					//Write 3-node triangle
					Point pt0 = fit->vertex(0)->point();
					Point pt1 = fit->vertex(1)->point();
					Point pt2 = fit->vertex(2)->point();
					out << "3 " << map_vts[pt0] << " " << map_vts[pt1] << " " << map_vts[pt2] <<  endl;
				}
			  }
			  out << endl;

			  // Write cell type
			  out << "CELL_TYPES " << ncells << endl;

		      for (int icell = 0; icell < ncells; icell++){
		    	  out << "5" << endl;
		      }
			  out << endl;

			  // Write node material id
			  out << "POINT_DATA " << nvtx << endl;
			  out << "SCALARS node_matids int 1" << endl;
			  out << "LOOKUP_TABLE default" << endl;
		      for (int ivtx = 0; ivtx < nvtx; ivtx++){
		    	  out << "1" << endl;
		      }
		      out << endl;

			  // Write cell material id
			  out << "CELL_DATA " << ncells << endl;
			  out << "SCALARS cell_matids int 1" << endl;
			  out << "LOOKUP_TABLE default" << endl;
		      for (int icell = 0; icell < ncells; icell++){
		    	  out << "1" << endl;
		      }
		      out << endl;
		  }
		  else if (terrain_layers_n > 1){
			  int ncells = mesh_faces_counter_tri2d*(terrain_layers_n-1);
			  out << "CELLS " << ncells << " " << ncells*7 << endl;

			  for (int ilayer = 0; ilayer < terrain_layers_n-1; ilayer++){
				  int idelt = ilayer*mesh_vertices_counter_tri2d;
				  int idelt2 = (ilayer+1)*mesh_vertices_counter_tri2d;
				  for(CDT::Finite_faces_iterator fit = mesh_cdt.finite_faces_begin();
						  fit != mesh_cdt.finite_faces_end(); ++fit){
					if (is_constrained){
					  if(fit->info().in_domain()){
						//Write 6-node prism
						Point pt0 = fit->vertex(0)->point();
						Point pt1 = fit->vertex(1)->point();
						Point pt2 = fit->vertex(2)->point();
						out << "6 " << map_vts[pt0]+idelt << " "
							<< map_vts[pt1]+idelt << " " << map_vts[pt2]+idelt << " "
							<< map_vts[pt0]+idelt2 << " " << map_vts[pt1]+idelt2 << " "
							<< map_vts[pt2]+idelt2 << endl;
					  }
					}
					else{
					  //Write 6-node prism
					  Point pt0 = fit->vertex(0)->point();
					  Point pt1 = fit->vertex(1)->point();
					  Point pt2 = fit->vertex(2)->point();
						out << "6 " << map_vts[pt0]+idelt << " "
							<< map_vts[pt1]+idelt << " " << map_vts[pt2]+idelt << " "
							<< map_vts[pt0]+idelt2 << " " << map_vts[pt1]+idelt2 << " "
							<< map_vts[pt2]+idelt2 << endl;
					}
				  }
			  }
			  out << endl;

			  // Write cell type
			  out << "CELL_TYPES " << ncells << endl;

		      for (int icell = 0; icell < ncells; icell++){
		    	  out << "13" << endl;
		      }
			  out << endl;

			  // Write node material id
			  out << "POINT_DATA " << nvtx << endl;
			  out << "SCALARS node_matids int 1" << endl;
			  out << "LOOKUP_TABLE default" << endl;
		      for (int ilayer = 0; ilayer < terrain_layers_n; ilayer++){
				  for(int ivtx = 0; ivtx < mesh_vertices_counter_tri2d; ivtx++){
					  out << ilayer+1 << endl;
				  }
		      }
		      out << endl;

			  // Write cell material id
			  out << "CELL_DATA " << ncells << endl;
			  out << "SCALARS cell_matids int 1" << endl;
			  out << "LOOKUP_TABLE default" << endl;

			  for (int ilayer = 0; ilayer < terrain_layers_n-1; ilayer++){
		          for (int icell = 0; icell < mesh_faces_counter_tri2d; icell++){
		    	      out << ilayer+1 << endl;
		          }
			  }
		      out << endl;
		  }

	  }
	  else{
		  out << "Error: output mesh format is unknown" << endl;
	  }
	  // Close file
	  out.close();
}

extern  "C" {

	// set temporatory points vector served as bridge between C++ and Fortran
	void set_vector_point_temp_tri2d(const int n, const point2d * pts){
		vector_point_temp_tri2d.clear();
		for (int i = 0; i < n; i++){
			vector_point_temp_tri2d.push_back(Point((pts+i)->x,(pts+i)->y));
		}
	}

	// set temporatory double vector served as bridge between C++ and Fortran
	void set_vector_double_temp_tri2d(const int n, const double * dvalue){
		vector_double_temp_tri2d.clear();
		for (int i = 0; i < n; i++){
			vector_double_temp_tri2d.push_back(dvalue[i]);
		}
	}

	// set temporatory integer vector served as bridge between C++ and Fortran
	void set_vector_int_temp_tri2d(const int n, const int * ivalue){
		vector_int_temp_tri2d.clear();
		for (int i = 0; i < n; i++){
			vector_int_temp_tri2d.push_back(ivalue[i]);
		}
	}

	// set points with index
	void set_mesh_points_tri2d(const int n, const point2d * pts){
		mesh_points_tri2d.clear();
		mesh_points_map.clear();
		for (int i = 0; i < n; i++){
			Point pt = Point((pts+i)->x, (pts+i)->y);
			mesh_points_tri2d.push_back(pt);
			mesh_points_map[pt] = i;
		}
	}

	// set layer elevation vector served as bridge between C++ and Fortran
	void set_terrain_layer_tri2d(const int nlayer, const int nvtx_perlayer,
			const double * dvalue){
		int k = 0;
		terrain_layers_n = nlayer;
		terrain_layers_z.clear();
		for (int i = 0; i < nlayer; i++){
			for (int j = 0; j< nvtx_perlayer; j++){
				terrain_layers_z.push_back(dvalue[k]);
				k++;
			}
		}
	}

	//
	//Insert a polyline into the CDT object, the polyline can be open or closed (connect the fist and last point)
	//Description of variables
	//	vp: Point vector to construct the polyline or polygon.
	//	isclosed: if true, it is closed, if false, it is open.
	//
	void insert_constraint_polyline_tri2d(const Vector_Point vp,
			const bool isclosed){
		insertConstraintPolyline_tri2d(vp,isclosed);
	}

	//
	//Insert a polyline into the CDT object, the polyline can be open or closed (connect the fist and last point)
	//Description of variables
	//	vp: Point vector to construct the polyline or polygon, using the temporatory global variable
	//	isclosed: if true, it is closed, if false, it is open.
	//
	void insert_constraint_polyline_tri2d_ex(const bool isclosed){
		insertConstraintPolyline_tri2d(vector_point_temp_tri2d,isclosed);
	}

	//
	//Insert a polyline with distance input for every segment into the CDT object,
	//the polyline can be open or closed (connect the fist and last point)
	//Description of variables
	//	vp: Point vector to construct the polyline or polygon.
	//	vd: double vector to define the point distribution interval in every segment
	//	isclosed: if true, it is closed, if false, it is open.
	//
	void insert_constraint_polyline_tri2d_d(const Vector_Point vp, const Vector_double vd,
			const bool isclosed){
		insertConstraintPolyline_tri2d(vp, vd, isclosed);
	}

	//
	//Insert a polyline with distance input for every segment into the CDT object,
	//the polyline can be open or closed (connect the fist and last point)
	//Description of variables
	//	vp: Point vector to construct the polyline or polygon, using the temporatory global variable
	//	vd: double vector to define the point distribution interval in every segment, using the temporatory global variable
	//	isclosed: if true, it is closed, if false, it is open.
	//
	void insert_constraint_polyline_tri2d_d_ex(const bool isclosed){
		insertConstraintPolyline_tri2d(vector_point_temp_tri2d, vector_double_temp_tri2d, isclosed);
	}

	//
	//Insert a polyline with distance input for every segment into the CDT object,
	//the polyline can be open or closed (connect the fist and last point)
	//Description of variables
	//	vp: Point vector to construct the polyline or polygon.
	//	vi: integer vector to define the number of interval in every segment
	//	isclosed: if true, it is closed, if false, it is open.
	//
	void insert_constraint_polyline_tri2d_n(const Vector_Point vp, const Vector_int vi,
			const bool isclosed){
		insertConstraintPolyline_tri2d(vp, vi, isclosed);
	}

	//
	//Insert a polyline with distance input for every segment into the CDT object,
	//the polyline can be open or closed (connect the fist and last point)
	//Description of variables
	//	vp: Point vector to construct the polyline or polygon, using the temporatory global variable
	//	vi: integer vector to define the number of interval in every segment, using the temporatory global variable
	//	isclosed: if true, it is closed, if false, it is open.
	//
	void insert_constraint_polyline_tri2d_n_ex(const Vector_Point vp, const Vector_int vi,
			const bool isclosed){
		insertConstraintPolyline_tri2d(vector_point_temp_tri2d, vector_int_temp_tri2d, isclosed);
	}

	//
	//Insert circle or arc into CDT object
	//Description of variables
	//  pt1, pt2 and pt3 are the given 3 points
	//  delt_arc: the given interval (arc length)
	//  isClosed: if true, this is a circle, otherwise, it's an arc in the direction pt1->pt2->pt3
	//
	void insert_constraint_circle_tri2d(const Point pt1, const Point pt2, const Point pt3,
			const double delt_arc, const bool isClosed){
		insertConstraintCircle_tri2d(pt1, pt2, pt3, delt_arc, isClosed);
	}

	//
	//Insert circle or arc into CDT object
	//Description of variables
	//  pt1, pt2 and pt3 are the given 3 points, using the temporatory global variable
	//  delt_arc: the given interval (arc length)
	//  isClosed: if true, this is a circle, otherwise, it's an arc in the direction pt1->pt2->pt3
	//
	void insert_constraint_circle_tri2d_ex(const double delt_arc, const bool isClosed){
		insertConstraintCircle_tri2d(vector_point_temp_tri2d[0], vector_point_temp_tri2d[1],
				vector_point_temp_tri2d[2], delt_arc, isClosed);
	}

	//Triangulation coordinate type
	//0-xy coordinate
	//1-yz coordinate
	//2-xz coordinate
	void set_coordinate_type_tri2d(const int itype){
		setCoordinateType_tri2d(itype);
	}

	// triangulation
	void make_mesh_tri2d(){
		triangulation2d();
	}

	// write mesh to file
	void output_triangulation_tri2d(const int nfile,const char* sfile,const int nformat,
			const char* sformat){
		  outputTriangulation2d(nfile,sfile,nformat,sformat);
	}

	// write prism mesh to file
	void output_triangulation_prism(const int nfile,const char* sfile,const int nformat,
			const char* sformat){
		  outputTriangulationPrism(nfile,sfile,nformat,sformat);
	}


	// number of finite vertices in the mesh, different from the number of points
	int number_of_finite_vertices_tri2d(){
		  return mesh_vertices_counter_tri2d;
	}

	// number of finite edges
	int number_of_finite_edges_tri2d(){
		  return mesh_edges_counter_tri2d;
	}

	// number of finite faces
	int number_of_finite_faces_tri2d(){
		  return mesh_faces_counter_tri2d;
	}
}


